567	func (r guardValueResolver) containsSeen(node ast.Node, want string, seen map[types.Object]bool) bool {
568		found := false
569		ast.Inspect(node, func(n ast.Node) bool {
570			switch value := n.(type) {
571			case *ast.BasicLit:
572				if value.Kind != token.STRING {
573					return true
574				}
575				unquoted, err := strconv.Unquote(value.Value)
576				if err == nil && unquoted == want {
577					found = true
578					return false
579				}
580			case *ast.Ident:
581				object := r.typeInfo.Uses[value]
582				if object == nil {
583					object = r.typeInfo.Defs[value]
584				}
585				if object == nil {
586					if r.packageValues[value.Name] == want {
587						found = true
588					}
589					return false
590				}
591				if seen[object] {
592					return false
593				}
594				expr := r.bindings[object]
595				if expr == nil {
596					return false
597				}
598				seen[object] = true
599				if r.containsSeen(expr, want, seen) {
600					found = true
601				}
602				delete(seen, object)
603				return false
604			}
605			return !found
606		})
607		return found
608	}
