104	func scanGitMetadataSources(repoRoot string, policy gitMetadataGuardPolicy) (gitMetadataGuardResult, error) {
105		packageValues, err := collectGuardPackageStringValues(repoRoot)
106		if err != nil {
107			return gitMetadataGuardResult{}, fmt.Errorf("collect package string values: %w", err)
108		}
109		fset := token.NewFileSet()
110		result := gitMetadataGuardResult{
111			legacyOwnersSeen:        map[string]bool{},
112			policyInspectionsSeen:   map[string]bool{},
113			metadataQueriesSeen:     map[guardMetadataQuery]bool{},
114			legacyResolverCallsSeen: map[string]bool{},
115		}
116	
117		err = filepath.WalkDir(repoRoot, func(path string, entry fs.DirEntry, walkErr error) error {
118			if walkErr != nil {
119				return walkErr
120			}
121			if entry.IsDir() {
122				return nil
123			}
124			rel, err := filepath.Rel(repoRoot, path)
125			if err != nil {
126				return err
127			}
128			rel = filepath.ToSlash(rel)
129			if !isGuardSourceFile(rel) {
130				return nil
131			}
132	
133			file, err := parser.ParseFile(fset, path, nil, 0)
134			if err != nil {
135				return err
136			}
137			values := packageValues[guardPackageKey(rel, file)]
138			valueResolver := newGuardValueResolver(fset, file, values)
139			gitrepoImports, dotImportedGitrepo := gitrepoImportNames(file)
140			samePackage := filepath.ToSlash(filepath.Dir(rel)) == "cmd/entire/cli/gitrepo"
141			for _, decl := range file.Decls {
142				fn, ok := decl.(*ast.FuncDecl)
143				if !ok || fn.Body == nil {
144					continue
145				}
146				key := guardSourceKey(rel, fn.Name.Name)
147				canonicalOwner := guardSourcePath(rel) == "gitrepo/metadata.go"
148				_, legacyOwner := policy.legacyTraversalOwners[key]
149				_, policyInspection := policy.policyDotGitInspections[key]
150	
151				for _, value := range []string{"gitdir: ", "gitdir:", "commondir"} {
152					if !valueResolver.contains(fn.Body, value) {
153						continue
154					}
155					if canonicalOwner {
156						result.canonicalTokens++
157						continue
158					}
159					if legacyOwner {
160						result.legacyOwnersSeen[key] = true
161						continue
162					}
163					result.violations = append(result.violations, fmt.Sprintf("%s independently parses Git metadata token %q; use gitrepo.ResolveWorktreeMetadata", fset.Position(fn.Pos()), value))
164				}
165				if valueResolver.contains(fn.Body, "rev-parse") {
166					for _, flag := range []string{"--absolute-git-dir", "--git-common-dir", "--git-dir", "--show-toplevel"} {
167						if !valueResolver.contains(fn.Body, flag) {
168							continue
169						}
170						query := guardMetadataQuery{source: key, flag: flag}
171						if _, allowed := policy.allowedMetadataQueries[query]; allowed {
172							result.metadataQueriesSeen[query] = true
173						} else {
174							result.violations = append(result.violations, fmt.Sprintf("%s runs an unaudited git rev-parse %s query; use gitrepo.ResolveWorktreeMetadata or document a semantic-query exception", fset.Position(fn.Pos()), flag))
175						}
176					}
177				}
178				ast.Inspect(fn.Body, func(node ast.Node) bool {
179					call, ok := node.(*ast.CallExpr)
180					if !ok {
181						return true
182					}
183					if isLegacyMetadataResolverCall(call, gitrepoImports, dotImportedGitrepo, samePackage) {
184						if _, allowed := policy.allowedLegacyCalls[key]; allowed {
185							result.legacyResolverCallsSeen[key] = true
186						} else {
187							result.violations = append(result.violations, fmt.Sprintf("%s calls a legacy Git metadata resolver; use gitrepo.ResolveWorktreeMetadata or document the migration exception", fset.Position(call.Pos())))
188						}
189					}
190					if !valueResolver.contains(call, ".git") || !isFilesystemMetadataInspection(call) || canonicalOwner {
191						return true
192					}
193					if legacyOwner {
194						result.legacyOwnersSeen[key] = true
195						return true
196					}
197					if policyInspection {
198						result.policyInspectionsSeen[key] = true
199						return true
200					}
201					result.violations = append(result.violations, fmt.Sprintf("%s independently inspects a .git entry; use gitrepo.ResolveWorktreeMetadata or document a narrow policy exception", fset.Position(call.Pos())))
202					return true
203				})
204			}
205			return nil
206		})
207		return result, err
208	}
