419	func packageStringValues(file *ast.File) map[string]string {
420		values := map[string]string{}
421		for _, decl := range file.Decls {
422			gen, ok := decl.(*ast.GenDecl)
423			if !ok {
424				continue
425			}
426			for _, spec := range gen.Specs {
427				valueSpec, ok := spec.(*ast.ValueSpec)
428				if !ok {
429					continue
430				}
431				for i, expr := range valueSpec.Values {
432					literal, ok := expr.(*ast.BasicLit)
433					if !ok || literal.Kind != token.STRING || i >= len(valueSpec.Names) {
434						continue
435					}
436					unquoted, err := strconv.Unquote(literal.Value)
437					if err == nil {
438						values[valueSpec.Names[i].Name] = unquoted
439					}
440				}
441			}
442		}
443		return values
444	}
