446	func gitrepoImportNames(file *ast.File) (map[string]bool, bool) {
447		names := map[string]bool{}
448		dotImported := false
449		for _, spec := range file.Imports {
450			path, err := strconv.Unquote(spec.Path.Value)
451			if err != nil || path != "github.com/entireio/cli/cmd/entire/cli/gitrepo" {
452				continue
453			}
454			switch {
455			case spec.Name == nil:
456				names["gitrepo"] = true
457			case spec.Name.Name == ".":
458				dotImported = true
459			case spec.Name.Name != "_":
460				names[spec.Name.Name] = true
461			}
462		}
463		return names, dotImported
464	}
