466	func isLegacyMetadataResolverCall(call *ast.CallExpr, importNames map[string]bool, dotImported, samePackage bool) bool {
467		legacyName := func(name string) bool {
468			return name == "ResolveDotGitPath" || name == "ResolveCommonGitPath"
469		}
470		if ident, ok := call.Fun.(*ast.Ident); ok {
471			return (dotImported || samePackage) && legacyName(ident.Name)
472		}
473		selector, ok := call.Fun.(*ast.SelectorExpr)
