25	// ResolveWorktreeMetadata resolves filesystem metadata for an explicit
26	// worktree root. It does not discover a root, inspect Git environment
27	// variables, run Git, cache results, or decide caller policy.
28	func ResolveWorktreeMetadata(worktreeRoot string) (WorktreeMetadata, error) {
29		if worktreeRoot == "" {
30			return WorktreeMetadata{}, errors.New("worktree root is required")
31		}
32	
33		root, err := filepath.Abs(worktreeRoot)
34		if err != nil {
35			return WorktreeMetadata{}, fmt.Errorf("resolve worktree root %q: %w", worktreeRoot, err)
36		}
37		root = filepath.Clean(root)
38		if err := requireMetadataDirectory("worktree root", root); err != nil {
39			return WorktreeMetadata{}, err
40		}
41	
42		gitDirPath, err := resolveWorktreeGitDir(root)
43		if err != nil {
44			return WorktreeMetadata{}, err
45		}
46		commonDir, err := resolveWorktreeCommonDir(gitDirPath)
47		if err != nil {
48			return WorktreeMetadata{}, err
49		}
50		worktreeID, err := resolveWorktreeID(gitDirPath, commonDir)
51		if err != nil {
52			return WorktreeMetadata{}, err
53		}
54	
55		return WorktreeMetadata{
56			GitDir:     gitDirPath,
57			CommonDir:  commonDir,
58			WorktreeID: worktreeID,
59		}, nil
60	}
