62	func resolveWorktreeGitDir(worktreeRoot string) (string, error) {
63		gitEntry := filepath.Join(worktreeRoot, gitDir)
64		info, err := os.Lstat(gitEntry)
65		if errors.Is(err, fs.ErrNotExist) {
66			if rootErr := requireMetadataDirectory("worktree root", worktreeRoot); rootErr != nil {
67				return "", rootErr
68			}
69			return "", fmt.Errorf("%w at %s: %w", ErrWorktreeMetadataNotFound, gitEntry, err)
70		}
71		if err != nil {
72			return "", fmt.Errorf("inspect .git entry at %s: %w", gitEntry, err)
73		}
74		if info.Mode()&fs.ModeSymlink != 0 {
75			info, err = os.Stat(gitEntry)
76			if err != nil {
77				return "", fmt.Errorf("inspect .git entry at %s: %w", gitEntry, err)
78			}
79		}
80		if info.IsDir() {
81			return gitEntry, nil
82		}
83		if !info.Mode().IsRegular() {
84			return "", fmt.Errorf(".git entry at %s is neither a directory nor a regular file", gitEntry)
85		}
86	
87		content, err := os.ReadFile(gitEntry) //nolint:gosec // path is anchored at the explicit worktree root.
88		if err != nil {
89			return "", fmt.Errorf("read .git file at %s: %w", gitEntry, err)
90		}
91		pointer, ok := strings.CutPrefix(strings.TrimRight(string(content), "\r\n"), "gitdir: ")
92		if !ok {
93			return "", fmt.Errorf("parse .git file at %s: missing gitdir prefix", gitEntry)
94		}
95		if pointer == "" {
96			return "", fmt.Errorf("parse .git file at %s: empty gitdir value", gitEntry)
97		}
98	
99		resolved, err := resolveMetadataDirectory("Git directory", worktreeRoot, pointer)
100		if err != nil {
101			return "", err
102		}
103		return resolved, nil
104	}
