191		repositoryFS := dotgit.NewRepositoryFilesystem(dotGitFS, commonGitFS)
192		// Shared clones write absolute object directories to objects/info/alternates;
193		// an OS-rooted filesystem lets go-git follow those paths outside .git.
194		storage := gitfilesystem.NewStorageWithOptions(
195			repositoryFS,
196			sharedObjectCache,
197			gitfilesystem.Options{
198				AlternatesFS: newAlternatesFilesystem(),
199			},

