// openBareRepository opens a path that carries no worktree metadata.
//
// Bareness is decided the way git decides it, which is not by reading core.bare
// as a required key: git's own test is that the directory holds HEAD, objects
// and refs, and entering such a directory directly makes it bare unless
// core.bare says otherwise. `git clone --bare` and `git init --bare` leave the
// key unset in the common case, so requiring it to be present and true rejects
// ordinary bare repositories that git — and this package before the metadata
// split — opens without complaint.
//
// The case that must still be refused is the separate Git directory
// (`git init --separate-git-dir`), which is a worktree's storage rather than a
// repository to open on its own. Git writes core.bare = false there explicitly,
// so an explicit false is the discriminator, and an absent key is not.
//
// PlainOpen supplies the shape check: it reports "repository does not exist"
// for a directory that only looks like one.
func openBareRepository(repoRoot string) (*git.Repository, error) {
	repo, err := git.PlainOpen(repoRoot)
	if err != nil {
		return nil, fmt.Errorf("failed to open repository: %w", err)
	}
	config, err := repo.Config()
	if err != nil {
		_ = repo.Close()
		return nil, fmt.Errorf("validate bare repository config: %w", err)
	}
	if config.Raw.Section("core").HasOption("bare") && !config.Core.IsBare {
		_ = repo.Close()
		return nil, fmt.Errorf("path %s has no worktree metadata and is not a bare repository", repoRoot)
	}
	return repo, nil
}

