type guardValueResolver struct {
	typeInfo *types.Info
	bindings map[types.Object]ast.Expr
}

// newGuardValueResolver type-checks a whole package at once, so an identifier
// declared in one file resolves from another, and a local name that shadows a
// package-level constant resolves to the local declaration.
//
// Checking one file at a time cannot do either, and the fallback that
// compensated for it — matching an unresolved identifier against package
// constants by name — reported a violation for any parameter, field, or local
// whose name happened to match a constant elsewhere in the package. That fires
// on `gitDir`, which strategy declares as a constant and several functions take
// as a parameter, so the guard failed the build for code that does nothing the
// guard is looking for and named neither the cause nor the fix. An identifier
// that still does not resolve now matches nothing.
func newGuardValueResolver(fset *token.FileSet, pkg guardPackage) guardValueResolver {
	typeInfo := &types.Info{
		Defs: map[*ast.Ident]types.Object{},
		Uses: map[*ast.Ident]types.Object{},
	}
	files := make([]*ast.File, 0, len(pkg.files))
	for _, source := range pkg.files {
		files = append(files, source.file)
	}
	name := "guard"
	if len(files) > 0 {
		name = files[0].Name.Name
	}
	// Imports are not resolved, so type errors are expected; the identifiers
	// declared inside the package are still recorded.
	config := types.Config{Error: func(error) {}, Importer: nil}
	_, _ = config.Check(name, fset, files, typeInfo)
	return guardValueResolver{
		typeInfo: typeInfo,
		bindings: guardValueBindings(files, typeInfo),
	}
}

func guardValueBindings(files []*ast.File, typeInfo *types.Info) map[types.Object]ast.Expr {
	bindings := map[types.Object]ast.Expr{}
	for _, file := range files {
		ast.Inspect(file, func(node ast.Node) bool {
			switch decl := node.(type) {
			case *ast.ValueSpec:
				for i, name := range decl.Names {
					if object := typeInfo.Defs[name]; object != nil {
						bindings[object] = expressionAt(decl.Values, i)
					}
				}
			case *ast.AssignStmt:
				if decl.Tok != token.DEFINE {
					return true
				}
				for i, lhs := range decl.Lhs {
					name, ok := lhs.(*ast.Ident)
					if !ok {
						continue
					}
					if object := typeInfo.Defs[name]; object != nil {
						bindings[object] = expressionAt(decl.Rhs, i)
					}
				}
			}
			return true
		})
	}
	return bindings
}

