// mainResolveDotGitPath is main's resolver, copied verbatim from
// origin/main cmd/entire/cli/gitrepo/repository.go.
func mainResolveDotGitPath(repoRoot string) (string, error) {
	gitPath := filepath.Join(repoRoot, ".git")
	info, err := os.Stat(gitPath)
	if err != nil {
		return "", fmt.Errorf("stat .git path: %w", err)
	}
	if info.IsDir() {
		return gitPath, nil
	}
	content, err := os.ReadFile(gitPath)
	if err != nil {
		return "", fmt.Errorf("read .git file: %w", err)
	}
	line, _, _ := strings.Cut(string(content), "\n")
	gitdir, ok := strings.CutPrefix(strings.TrimSpace(line), "gitdir:")
	if !ok {
		return "", errors.New(".git file has no gitdir prefix")
	}
	gitdir = strings.TrimSpace(gitdir)
	if filepath.IsAbs(gitdir) {
		return filepath.Clean(gitdir), nil
	}
	return filepath.Clean(filepath.Join(repoRoot, gitdir)), nil
}

func probe(label string, fn func() (string, error)) {
	done := make(chan error, 1)
	go func() { _, err := fn(); done <- err }()
	select {
	case err := <-done:
		fmt.Printf("  %-28s returned: %v\n", label, err)
	case <-time.After(3 * time.Second):
		fmt.Printf("  %-28s *** STILL BLOCKED after 3s ***\n", label)
	}
}

func main() {
	for _, kind := range []string{"fifo", "symlink-to-fifo", "symlink-to-dev-zero"} {
		root, err := os.MkdirTemp("", "hang")
		if err != nil {
			panic(err)
		}
		dotGit := filepath.Join(root, ".git")
		switch kind {
		case "fifo":
			if err := syscall.Mkfifo(dotGit, 0o600); err != nil {
				panic(err)
			}
		case "symlink-to-fifo":
			target := filepath.Join(root, "pipe")
			if err := syscall.Mkfifo(target, 0o600); err != nil {
				panic(err)
			}
			if err := os.Symlink(target, dotGit); err != nil {
				panic(err)
			}
		case "symlink-to-dev-zero":
			if err := os.Symlink("/dev/zero", dotGit); err != nil {
				panic(err)
			}
		}
		fmt.Printf("%s:\n", kind)
		probe("main resolveDotGitPath", func() (string, error) { return mainResolveDotGitPath(root) })
	}
}
